document.addEventListener("DOMContentLoaded",(()=>{fetch("/standings_data/").then((e=>{if(!e.ok)throw new Error("Network response was not ok");return e.json()})).then((e=>{console.log(e);const t=e,n=document.getElementById("standings-container");let o=1;for(const e of t){const t=document.createElement("tr"),r=document.createElement("th");r.scope="row",r.textContent=o,o+=1,t.appendChild(r);for(const n of["Team","GP","W","L","D","PCT","PF","PA","PD"]){const o=document.createElement("td");o.textContent=e[n],t.appendChild(o)}n.appendChild(t)}})).catch((e=>{console.error("There was a problem with the fetch operation:",e)}))}));